from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class CAType(SchemaObject):
    name = SchemaField(name='name', not_null=True)
    value = SchemaField(name='value', not_null=True)

    def __init__(self, name, value):
        self.name = name
        self.value = value

        super(CAType, self).__init__()


class Details(SchemaObject):
    issued_to = SchemaField(name='issued_to', not_null=True)
    issued_by = SchemaField(name='issued_by', not_null=True)
    valid_from = SchemaField(name='valid_from', not_null=True)
    valid_to = SchemaField(name='valid_to', not_null=True)
    serial_number = SchemaField(name='serial_number', not_null=True)
    ca_type = SchemaField(name='ca_type', klass=CAType, optional=True)

    def __init__(self, issued_to, issued_by, valid_from, valid_to, serial_number, ca_type):
        self.issued_to = issued_to
        self.issued_by = issued_by
        self.valid_from = valid_from
        self.valid_to = valid_to
        self.serial_number = serial_number
        self.ca_type = ca_type

        super(Details, self).__init__()


class CertificatesInfo(SchemaObject):
    id = SchemaField(name='id', not_null=True)
    type = SchemaField(name='type', not_null=True)
    details = SchemaField(name='details', klass=Details, not_null=True)

    def __init__(self, id, type, details):
        self.id = id
        self.type = type
        self.details = details

        super(CertificatesInfo, self).__init__()
